-- ZipGo schema (oracle). Generated by src/db/print-schema.js

CREATE TABLE businesses (
  id VARCHAR2(36) PRIMARY KEY,
  phone VARCHAR2(20 CHAR) NOT NULL,
  business_name VARCHAR2(150 CHAR) NOT NULL,
  email VARCHAR2(150 CHAR),
  business_type VARCHAR2(40 CHAR) NOT NULL,
  address VARCHAR2(500 CHAR) NOT NULL,
  landmark VARCHAR2(200 CHAR),
  lat NUMBER NOT NULL,
  lng NUMBER NOT NULL,
  status VARCHAR2(20 CHAR) DEFAULT 'active' NOT NULL,
  created_at TIMESTAMP NOT NULL,
  updated_at TIMESTAMP NOT NULL,
  CONSTRAINT uq_businesses_phone UNIQUE (phone)
);

CREATE TABLE riders (
  id VARCHAR2(36) PRIMARY KEY,
  phone VARCHAR2(20 CHAR) NOT NULL,
  full_name VARCHAR2(120 CHAR) NOT NULL,
  email VARCHAR2(150 CHAR),
  cnic VARCHAR2(15 CHAR) NOT NULL,
  vehicle_type VARCHAR2(20 CHAR) NOT NULL,
  vehicle_plate VARCHAR2(20 CHAR) NOT NULL,
  city VARCHAR2(60 CHAR) DEFAULT 'Lahore' NOT NULL,
  status VARCHAR2(20 CHAR) DEFAULT 'offline' NOT NULL,
  rating NUMBER DEFAULT 5 NOT NULL,
  total_deliveries NUMBER(10) DEFAULT 0 NOT NULL,
  is_active NUMBER(1) DEFAULT 1 NOT NULL,
  last_lat NUMBER,
  last_lng NUMBER,
  location_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL,
  updated_at TIMESTAMP NOT NULL,
  CONSTRAINT uq_riders_phone UNIQUE (phone),
  CONSTRAINT uq_riders_cnic UNIQUE (cnic)
);

CREATE TABLE orders (
  id VARCHAR2(36) PRIMARY KEY,
  order_number VARCHAR2(20 CHAR) NOT NULL,
  tracking_code VARCHAR2(16 CHAR),
  business_id VARCHAR2(36) NOT NULL,
  rider_id VARCHAR2(36),
  order_type VARCHAR2(20 CHAR) NOT NULL,
  pickup_name VARCHAR2(150 CHAR) NOT NULL,
  pickup_address VARCHAR2(500 CHAR) NOT NULL,
  pickup_lat NUMBER NOT NULL,
  pickup_lng NUMBER NOT NULL,
  drop_name VARCHAR2(120 CHAR) NOT NULL,
  drop_phone VARCHAR2(20 CHAR),
  drop_address VARCHAR2(500 CHAR) NOT NULL,
  drop_lat NUMBER NOT NULL,
  drop_lng NUMBER NOT NULL,
  package_details VARCHAR2(500 CHAR),
  weight_kg NUMBER,
  distance_km NUMBER NOT NULL,
  duration_mins NUMBER(10) NOT NULL,
  route_approximate NUMBER(1) DEFAULT 0 NOT NULL,
  fare NUMBER NOT NULL,
  final_fare NUMBER,
  is_peak NUMBER(1) DEFAULT 0 NOT NULL,
  status VARCHAR2(20 CHAR) NOT NULL,
  decline_count NUMBER(10) DEFAULT 0 NOT NULL,
  failure_reason VARCHAR2(300 CHAR),
  created_at TIMESTAMP NOT NULL,
  accepted_at TIMESTAMP,
  picked_up_at TIMESTAMP,
  delivered_at TIMESTAMP,
  cancelled_at TIMESTAMP,
  updated_at TIMESTAMP NOT NULL,
  CONSTRAINT uq_orders_number UNIQUE (order_number),
  CONSTRAINT fk_orders_business FOREIGN KEY (business_id) REFERENCES businesses (id),
  CONSTRAINT fk_orders_rider FOREIGN KEY (rider_id) REFERENCES riders (id)
);

CREATE TABLE order_declines (
  order_id VARCHAR2(36) NOT NULL,
  rider_id VARCHAR2(36) NOT NULL,
  reason VARCHAR2(30 CHAR) NOT NULL,
  created_at TIMESTAMP NOT NULL,
  CONSTRAINT pk_order_declines PRIMARY KEY (order_id, rider_id),
  CONSTRAINT fk_declines_order FOREIGN KEY (order_id) REFERENCES orders (id),
  CONSTRAINT fk_declines_rider FOREIGN KEY (rider_id) REFERENCES riders (id)
);

CREATE TABLE earnings (
  id VARCHAR2(36) PRIMARY KEY,
  rider_id VARCHAR2(36) NOT NULL,
  order_id VARCHAR2(36) NOT NULL,
  amount NUMBER NOT NULL,
  created_at TIMESTAMP NOT NULL,
  CONSTRAINT uq_earnings_order UNIQUE (order_id),
  CONSTRAINT fk_earnings_rider FOREIGN KEY (rider_id) REFERENCES riders (id),
  CONSTRAINT fk_earnings_order FOREIGN KEY (order_id) REFERENCES orders (id)
);

CREATE TABLE menu_items (
  id VARCHAR2(36) PRIMARY KEY,
  business_id VARCHAR2(36) NOT NULL,
  item_name VARCHAR2(150 CHAR) NOT NULL,
  price NUMBER NOT NULL,
  in_stock NUMBER(1) DEFAULT 1 NOT NULL,
  created_at TIMESTAMP NOT NULL,
  updated_at TIMESTAMP NOT NULL,
  CONSTRAINT fk_menu_business FOREIGN KEY (business_id) REFERENCES businesses (id)
);

CREATE TABLE otp_codes (
  phone VARCHAR2(20 CHAR) NOT NULL,
  user_role VARCHAR2(20 CHAR) NOT NULL,
  code_hash VARCHAR2(64 CHAR) NOT NULL,
  attempts NUMBER(10) DEFAULT 0 NOT NULL,
  expires_at TIMESTAMP NOT NULL,
  created_at TIMESTAMP NOT NULL,
  CONSTRAINT pk_otp_codes PRIMARY KEY (phone, user_role)
);

CREATE TABLE support_tickets (
  id VARCHAR2(36) PRIMARY KEY,
  business_id VARCHAR2(36) NOT NULL,
  message VARCHAR2(2000 CHAR) NOT NULL,
  status VARCHAR2(20 CHAR) DEFAULT 'open' NOT NULL,
  created_at TIMESTAMP NOT NULL,
  CONSTRAINT fk_support_business FOREIGN KEY (business_id) REFERENCES businesses (id)
);

CREATE TABLE daily_counters (
  counter_day VARCHAR2(8 CHAR) PRIMARY KEY,
  last_value NUMBER(10) NOT NULL
);

ALTER TABLE orders ADD (tracking_code VARCHAR2(16 CHAR));

CREATE INDEX ix_orders_business ON orders (business_id, created_at);

CREATE INDEX ix_orders_rider ON orders (rider_id, status);

CREATE INDEX ix_orders_status ON orders (status);

CREATE INDEX ix_riders_status ON riders (status);

CREATE INDEX ix_menu_business ON menu_items (business_id);

CREATE INDEX ix_earnings_rider ON earnings (rider_id, created_at);

CREATE UNIQUE INDEX ux_orders_tracking ON orders (tracking_code);

